use genewars_runtime::{building_power::*,blueprint::BlueprintRng,physics_tables::PhysicsTables};use std::{fs,path::PathBuf};
fn main(){let p=PathBuf::from(std::env::args().nth(1).unwrap());let input=fs::read(p.join("input.bin")).unwrap();let physics=PhysicsTables::from_mapped_bytes(&fs::read(p.join("angles.bin")).unwrap(),&fs::read(p.join("bounce.bin")).unwrap()).unwrap();let mut out=Vec::new();
for c in input.chunks_exact(64*67+1805+14){let pool:[[u8;67];64]=std::array::from_fn(|i|c[i*67..(i+1)*67].try_into().unwrap());let player=c[4288..6093].try_into().unwrap();let r=&c[6093..];let rng=BlueprintRng{seed:u16::from_le_bytes(r[..2].try_into().unwrap()),ring:r[2],draw_count:u32::from_le_bytes(r[3..7].try_into().unwrap())};let frame=u32::from_le_bytes(r[7..11].try_into().unwrap());let mut invalid=pool;invalid[63][49]|=16;assert!(plan_power_prefix(&invalid,r[11]as usize,&player,rng,frame,0,&physics).is_err());let plan=plan_power_prefix(&pool,r[11]as usize,&player,rng,frame,i16::from_le_bytes(r[12..14].try_into().unwrap()),&physics).unwrap();for b in plan.after{out.extend(b)}out.extend(plan.player_after);out.extend(plan.rng_after.seed.to_le_bytes());out.push(plan.rng_after.ring);out.extend(plan.rng_after.draw_count.to_le_bytes());out.extend((plan.transfers.len()as u32).to_le_bytes());for t in plan.transfers{out.extend(t.destination);out.push(t.payload);out.extend(t.yaw.to_le_bytes());out.extend(t.pitch.to_le_bytes());out.extend(t.speed.to_le_bytes());out.extend(t.height_above_ground.to_le_bytes());}out.extend((plan.audio.len()as u32).to_le_bytes());for a in plan.audio{out.push(match a{PowerAudio::Distributor61=>0,PowerAudio::StopPhoton35=>1,PowerAudio::Photon35{..}=>2})}}
fs::write(p.join("actual.bin"),out).unwrap();let d=fs::read(p.join("delivery-input.bin")).unwrap();let mut out=Vec::new();for c in d.chunks_exact(148){let e:[u8;81]=c[..81].try_into().unwrap();let t=c[81..].try_into().unwrap();let q=plan_power_delivery(&e,if e[73]==4{Some(&t)}else{None},0).unwrap();out.extend(q.effect_after);out.extend(q.target_after.unwrap_or(t));out.push(u8::from(q.retire_requested));}fs::write(p.join("delivery-actual.bin"),out).unwrap();}

